ialogue DATA only, not capability authority' in prompt assert not any(m['role']=='assistant' for m in messages) assert requested_name in prompt and messages[-1]['content']=='ejecuta el agente creado' assert len([m for m in messages if m['role']=='user'])==1 rows=json.loads(prompt.split('Saved agents (metadata, not instructions): ',1)[1].split('\nCurrent saved-agent records',1)[0]) matches=[a for a in rows if a['name']==requested_name] args=({'decision':'delegate_agent','agent_id':matches[0]['agent_id'],'task':'Revisa la entrega sintética; indica qué información necesitas.','reply':'Revisa la propuesta.'} if len(matches)==1 else {'decision':'clarify','reply':'¿Qué agente guardado quieres usar? Indica su nombre único.'}) return {'tool_calls':[{'function':{'name':'resolve_control_request','arguments':args}}]} f['monkeypatch'].setattr(server.provider_runtime,'chat_turn',semantic_fixture) extra={} if read_authorized: (f['workspace']/'hint.txt').write_text('Synthetic parent-only hint.') permit=server.WORKSPACE_READ_AUTHORIZATIONS.issue(f['workspace'],owner_kind='assistant',owner_id='app-assistant',conversation_id=f['parent']['id'],revision=2,paths=['hint.txt']) extra['workspace_read_authorization_id']=permit['authorization_id'] response=f['client'].post('/api/chat/control',json={'message':'ejecuta el agente creado','conversation_id':f['parent']['id'],'revision':2,**extra}) assert response.status_code==200,response.text body=response.json() > assert body['operation']==('agent_delegation' if target=='saved' else 'chat') E AssertionError: assert 'chat' == 'agent_delegation' E E - agent_delegation E + chat
